//! M14 audio adapter extract suite: the committed fixture corpus
//! (wav/mp3/flac/ogg, generated by one dev-time ffmpeg run and committed -
//! tests read bytes only, hermetic) extracts codec/rate/channels/duration
//! pinned; the opus fixture redirects typed to the M17 ffmpeg lane; a
//! truncated mp3 fails the typed ParseFailure; budget trips are typed;
//! descriptor claims and dispatch wiring are in place. Ground truth for
//! the pins: ffprobe (codec/rate/channels/duration) + ffmpeg astats
//! (peak -18.06 dB = 0.125 linear, the lavfi sine default amplitude;
//! RMS -21.07 dB = 0.0883 ~ 0.125/sqrt(2)), recorded in the M14 evidence.

use harness_media::adapter::audio;
use harness_media::error::MediaError;
use harness_media::executor::OpRequest;
use harness_media::extract::ExtractBudgets;
use harness_media::format::FormatId;

const WAV: &[u8] = include_bytes!("../fixtures/audio/sine-440-16k-mono.wav");
const FLAC: &[u8] = include_bytes!("../fixtures/audio/sine-440-16k-mono.flac");
const MP3: &[u8] = include_bytes!("../fixtures/audio/sine-440-22k-mono.mp3");
const OGG: &[u8] = include_bytes!("../fixtures/audio/sine-440-16k-mono.ogg");
/// The M2 probe-lane opus stub (OggS + OpusHead page): decode attempts on
/// it must redirect typed BEFORE any decode loop runs.
const OPUS: &[u8] = include_bytes!("../fixtures/opus.opus");
/// The corpus mp3 cut inside the first frame: no decodable packet exists.
const MP3_TRUNCATED: &[u8] = include_bytes!("../fixtures/audio/mp3-truncated.mp3");

fn extract(bytes: &[u8]) -> harness_media::extract::Extracted {
    audio::extract(bytes, ExtractBudgets::default()).expect("fixture must extract")
}

/// (bytes, codec, sample_rate, channels, per-channel sample count,
/// duration secs)
type CorpusRow = (&'static [u8], &'static str, u32, usize, u64, f64);
const CORPUS: &[CorpusRow] = &[
    (WAV, "pcm_s16le", 16_000, 1, 8_000, 0.5),
    (FLAC, "flac", 16_000, 1, 8_000, 0.5),
    (MP3, "mp3", 22_050, 1, 11_025, 0.5),
    (OGG, "vorbis", 16_000, 1, 8_000, 0.5),
];

#[test]
fn fixture_corpus_extracts_codec_rate_channels_duration_pinned() {
    // Given: the committed corpus (ffprobe ground truth pinned per file).
    for &(bytes, codec, rate, channels, samples, duration) in CORPUS {
        // When: extracted.
        let extracted = extract(bytes);
        let tree = &extracted.tree;
        // Then: codec, rate, channels, per-channel sample count and the
        // duration derived from them are exactly pinned.
        assert_eq!(tree["codec"], serde_json::json!(codec), "codec pin");
        assert_eq!(tree["sample_rate"], serde_json::json!(rate), "rate pin");
        assert_eq!(tree["channels"], serde_json::json!(channels), "channel pin");
        assert_eq!(tree["samples"], serde_json::json!(samples), "sample pin");
        let decoded_duration = tree["duration_secs"].as_f64().unwrap_or(f64::NAN);
        assert!(
            (decoded_duration - duration).abs() < 1e-9,
            "duration {decoded_duration} != {duration}"
        );
        // And: the amplitude analysis is at TRUE scale (the lavfi sine
        // amplitude is 0.125; a wrong integer normalization lands orders
        // of magnitude off - this pin is the scale guard).
        let peak = tree["peak"].as_f64().unwrap_or(f64::NAN);
        let rms = tree["rms"].as_f64().unwrap_or(f64::NAN);
        assert!((peak - 0.125).abs() < 0.02, "peak {peak} ~ 0.125");
        assert!((rms - 0.088_3).abs() < 0.02, "rms {rms} ~ 0.0883");
        // And: the waveform-peak thumbnail array is 256 buckets, each in
        // (0, 0.126] for this fixture (a constant sine stays loud end to
        // end).
        let peaks = tree["waveform_peaks"].as_array().expect("peaks array");
        assert_eq!(peaks.len(), audio::WAVEFORM_PEAK_BUCKETS);
        for bucket in peaks {
            let value = bucket.as_f64().unwrap_or(f64::NAN);
            assert!(
                value > 0.05 && value <= 0.13,
                "bucket {value} in the sine's live range"
            );
        }
    }
}

#[test]
fn text_projection_is_the_codec_hz_ch_mmss_line() {
    // Given: the wav fixture.
    let extracted = extract(WAV);
    // Then: the projection follows the plan's format
    // "audio: <codec> <hz>Hz <ch>ch <mm:ss>", and never fabricates a
    // transcript (the transcript slot is model-mediated only, M10).
    assert_eq!(
        extracted.text_projection, "audio: pcm_s16le 16000Hz 1ch 0:00",
        "the projection is the pinned one-line summary"
    );
    assert!(
        extracted.text_projection.chars().count()
            <= harness_media::extract::TEXT_PROJECTION_MAX_CHARS
    );
    assert!(
        extracted.thumbnails.is_empty(),
        "v0.2 audio ships no thumbnail artifacts (peaks live in the tree)"
    );
}

#[test]
fn opus_decode_is_typed_redirect_to_the_m17_ffmpeg_lane() {
    // Given: opus bytes (symphonia has no opus decoder; the digest 3.4
    // verdict and the plan route opus decode through ffmpeg at M17).
    // When: the pure-lane extract is called directly.
    let error = audio::extract(OPUS, ExtractBudgets::default())
        .expect_err("opus must never decode in the pure path");
    // Then: typed UnsupportedOperation naming the ffmpeg/M17 redirect.
    match error {
        MediaError::UnsupportedOperation { format, op, reason } => {
            assert_eq!(format, FormatId::Opus);
            assert_eq!(op, harness_media::descriptor::Operation::Extract);
            assert!(
                reason.contains("ffmpeg") && reason.contains("M17"),
                "reason names the subprocess lane: {reason}"
            );
        }
        other => panic!("expected UnsupportedOperation, got {other:?}"),
    }
    // And: the executor dispatch of opus extract stays the decided
    // subprocess lane (typed ToolUnavailable with ffmpeg while the tool
    // is not enabled - the M15 default).
    let dispatched = harness_media::executor::registry()
        .dispatch(
            FormatId::Opus,
            OpRequest::Extract {
                bytes: OPUS,
                budgets: ExtractBudgets::default(),
            },
        )
        .expect_err("opus extract dispatch must be typed-unavailable");
    match dispatched {
        MediaError::ToolUnavailable { tool, .. } => assert_eq!(tool, "ffmpeg"),
        other => panic!("expected ToolUnavailable, got {other:?}"),
    }
}

#[test]
fn truncated_mp3_fails_typed_parse_failure_never_panics() {
    // Given: the corpus mp3 truncated inside the first frame (no
    // decodable packet exists).
    // When: extracted.
    let error = audio::extract(MP3_TRUNCATED, ExtractBudgets::default())
        .expect_err("an undecodable stream must fail typed");
    // Then: ParseFailure - never a panic, never a fabricated extraction.
    assert!(matches!(error, MediaError::ParseFailure), "got {error:?}");
}

#[test]
fn extract_budget_trip_is_the_typed_extract_too_large() {
    // Given: a real fixture under a one-byte materialization cap.
    let budgets = ExtractBudgets {
        deadline: harness_media::extract::DEFAULT_EXTRACT_DEADLINE,
        max_total_bytes: 1,
    };
    // When/Then: the typed ExtractTooLarge, before any unbounded loop.
    let error = audio::extract(WAV, budgets).expect_err("cap must trip typed");
    assert!(
        matches!(error, MediaError::ExtractTooLarge),
        "got {error:?}"
    );
}

#[test]
fn audio_family_ops_are_dispatchable_with_producer_disclosure() {
    // Given: the wired executor registry (audio feature on via the
    // dev-dependency self-reference).
    let registry = harness_media::executor::registry();
    // Then: the descriptor claims the landed surface: extract on
    // wav/flac/mp3/ogg, generate+verify on wav/flac (mp3/ogg stay
    // decode-only with the encode redirect pinned elsewhere).
    let descriptors = harness_media::probe::registry();
    for id in [FormatId::Wav, FormatId::Flac, FormatId::Mp3, FormatId::Ogg] {
        let claim = descriptors
            .lookup(&id)
            .expect("descriptor")
            .ops
            .get(&harness_media::descriptor::Operation::Extract)
            .expect("extract claim");
        assert!(
            matches!(claim, harness_media::descriptor::OpSupport::Supported),
            "{id} extract must be Supported"
        );
    }
    for id in [FormatId::Wav, FormatId::Flac] {
        for op in [
            harness_media::descriptor::Operation::Generate,
            harness_media::descriptor::Operation::Verify,
        ] {
            let claim = descriptors
                .lookup(&id)
                .expect("descriptor")
                .ops
                .get(&op)
                .expect("op claim");
            assert!(
                matches!(claim, harness_media::descriptor::OpSupport::Supported),
                "{id} {op} must be Supported"
            );
        }
    }
    // And: dispatching extract through the executor carries the audio
    // producer disclosure (pure tier, named engine).
    let produced = registry
        .dispatch(
            FormatId::Wav,
            OpRequest::Extract {
                bytes: WAV,
                budgets: ExtractBudgets::default(),
            },
        )
        .expect("wav extract dispatches");
    let producer = produced.producer();
    assert_eq!(producer.tier, harness_media::executor::AdapterTier::Pure);
    assert_eq!(producer.engine, audio::ENGINE);
    assert!(matches!(
        produced.inner(),
        harness_media::executor::OpOutput::Extract(_)
    ));
}
